<script lang="ts">let{value,max=100,label,showValue=false}:{value:number;max?:number;label?:string;showValue?:boolean}=$props();const amount=$derived(Math.min(max,Math.max(0,value)));</script>
<div class="ds-progress">{#if label||showValue}<div class="meta"><span>{label||''}</span>{#if showValue}<span>{Math.round(max>0?amount/max*100:0)}%</span>{/if}</div>{/if}<div class="track" role="progressbar" aria-label={label||'Progress'} aria-valuemin="0" aria-valuemax={max} aria-valuenow={amount}><span style={'width:'+(max>0?amount/max*100:0)+'%'}></span></div></div>
<style>.ds-progress{display:grid;gap:.5rem}.meta{display:flex;justify-content:space-between;font:.75rem var(--ds-font);color:var(--ds-muted)}.track{height:.5rem;border-radius:999px;background:var(--ds-border);overflow:hidden}.track span{display:block;height:100%;background:var(--ds-primary);transition:width 220ms}</style>